    const float r0 = (float)ns_Rc[0], r1 = (float)ns_Rc[1], r2 = (float)ns_Rc[2], r3 = (float)ns_Rc[3], r4 = (float)ns_Rc[4], r5 = (float)ns_Rc[5], r6 = (float)ns_Rc[6], r7 = (float)ns_Rc[7], r8 = (float)ns_Rc[8];
